    for (String str : strings) {
        int n = str.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String substring = str.substring(i, j);
                substrings.add(substring);
                substrings.add(new StringBuilder(substring).reverse().toString());
            }
        }
