                int current = queue.poll();
                if (current > high) {
                    break;
                }
                int lastDigit = current % 10;
                if (lastDigit > 0) {
                    int next = current * 10 + (lastDigit - 1);
                    if (next >= low && next <= high) {
                        result.add(next);
                    }
                    queue.add(next);
