                if (lastDigit < 9) {
                    int next = current * 10 + (lastDigit + 1);
                    if (next >= low && next <= high) {
                        result.add(next);
                    }
                    queue.add(next);
                }
            }
        }
        result.sort(Integer::compareTo);
